	@Test
	public void testSuccess() {
		EmbeddedChannel channel = new EmbeddedChannel(new LoggingHandler(LogLevel.DEBUG), new Socks5InitialRequestDecoder());
		channel.writeInbound(Unpooled.wrappedBuffer(new byte[]{5, 2, 0, 1}));
		Object o = channel.readInbound();
		System.out.println("EmbeddedRead --->" + o);
		// EmbeddedRead --->DefaultSocks5InitialRequest(authMethods: [NO_AUTH(0), GSSAPI(1)])
	}

	/*
	* if Network unpacking will Fail
	* */
	@Test
	public void testFail() {
		EmbeddedChannel channel = new EmbeddedChannel(new LoggingHandler(LogLevel.DEBUG), new Socks5InitialRequestDecoder());
		channel.writeInbound(Unpooled.wrappedBuffer(new byte[]{5, 2, 0}));
		channel.writeInbound(Unpooled.wrappedBuffer(new byte[]{1}));
		Object o = channel.readInbound();
		System.out.println("EmbeddedRead --->" + o);
		//EmbeddedRead --->DefaultSocks5InitialRequest(decoderResult: failure(io.netty.handler.codec.DecoderException: unsupported version: 0 (expected: 5)), authMethods: [NO_AUTH(0)])
	}


```
